package core

// StoryCounts tallies story statuses by lifecycle bucket for an RFC's progress
// label: total, done, and open (everything not done). Closed stories are
// terminal won't-do work, so they drop out of the total entirely rather than
// inflating it and making an otherwise-finished RFC look unfinished.
func StoryCounts(statuses []string) (total, done, open int) {
	for _, st := range statuses {
		switch st {
		case "closed":
			continue
		case "done":
			total++
			done++
		default:
			total++
			open++
		}
	}
	return total, done, open
}
